/**
 * How Six hollyhocks in a wheel (`mutsu-aoi-guruma`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/mutsu-aoi-guruma";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Six hollyhock leaves point outward around a round hub. Two slender stalks from each leaf form the spokes of the wheel.","ja":"六枚の葵の葉を、丸い軸のまわりに葉先を外へ向けて置きます。葉の根元から細い茎を二本ずつ伸ばし、車の輻のように軸へつなぎます。"};

export default construction;
export { construction, description };
